using ByteEngine.Core.Plugins;
using ByteEngine.Core.Variables;
using ByteEngine.Core.VisualLogic;
namespace KarlsonDemo.Plugin;
internal static class MiningMarketEvents
{
 public static void Register(ByteEnginePluginContext c)
 {
  const string prefix="bytebard.karlsondemo.mining.";
  var target=new VisualArgumentDefinition("target","Workshop / market object",VariableValue.FromString("Self")){IsObjectReference=true};
  MiningTrade3D? Trade(VisualInstruction i,EventExecutionContext e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningTrade3D>();
  c.RegisterAction(new(){Id=prefix+"acceptDeliveryContract",Category="Mining",MenuGroup="Delivery contracts",DisplayName="Accept a delivery order",Arguments=[target,new("index","Order index (0 to 2)",VariableValue.FromNumber(0))],Execute=(i,e)=>Trade(i,e)?.AcceptDeliveryContract((int)EventValueResolver.GetNumber(i,"index",e))});
  c.RegisterAction(new(){Id=prefix+"deliverContract",Category="Mining",MenuGroup="Delivery contracts",DisplayName="Deliver the accepted order",Arguments=[target],Execute=(i,e)=>Trade(i,e)?.DeliverContract()});
  c.RegisterCondition(new(){Id=prefix+"deliveryContractReady",Category="Mining",MenuGroup="Delivery contracts",DisplayName="Accepted order has enough refined ore",Arguments=[target],Evaluate=(i,e)=>Trade(i,e) is {} t&&t.ActiveDeliveryContract is {} order&&t.Stock(true)>=order.Quantity&&!t.SaleInProgress});
  var operation=new VisualArgumentDefinition("target","Mining operation object",VariableValue.FromString("Self")){IsObjectReference=true};
  c.RegisterAction(new(){Id=prefix+"skipCampTutorial",Category="Mining",MenuGroup="Tutorial",DisplayName="Finish the camp tutorial",Arguments=[operation],Execute=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningOperation3D>()?.SkipCampTutorial()});
  c.RegisterCondition(new(){Id=prefix+"campTutorialStep",Category="Mining",MenuGroup="Tutorial",DisplayName="Camp tutorial is at step",Arguments=[operation,new("step","Step",VariableValue.FromString("AmmoPress")){Choices=Enum.GetNames<CampTutorialStep>()}],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningOperation3D>() is {} op&&op.TutorialActive&&op.TutorialStep.ToString()==EventValueResolver.GetString(i,"step",e)});
  c.RegisterAction(new(){Id=prefix+"beginMarketSale",Category="Mining",MenuGroup="Market",DisplayName="Sell ore or fulfil the accepted delivery order",Arguments=[target,new("refined","Refined ore",VariableValue.FromBoolean(true)),new("quantity","Ore quantity",VariableValue.FromNumber(20)),new("guaranteed","Fulfil accepted delivery contract",VariableValue.FromBoolean(false))],Execute=(i,e)=>Trade(i,e)?.BeginMarketSale(EventValueResolver.GetBoolean(i,"refined",e,true),(int)Math.Clamp(EventValueResolver.GetNumber(i,"quantity",e),0,1000000),EventValueResolver.GetBoolean(i,"guaranteed",e))});
  c.RegisterAction(new(){Id=prefix+"buyOre",Category="Mining",MenuGroup="Market",DisplayName="Buy ore at the live ask price",Arguments=[target,new("refined","Refined ore",VariableValue.FromBoolean(true)),new("quantity","Ore quantity",VariableValue.FromNumber(20))],Execute=(i,e)=>Trade(i,e)?.BuyOre(EventValueResolver.GetBoolean(i,"refined",e,true),(int)Math.Clamp(EventValueResolver.GetNumber(i,"quantity",e),0,1000000))});
  c.RegisterCondition(new(){Id=prefix+"marketSaleActive",Category="Mining",MenuGroup="Market",DisplayName="An accepted ore sale is shipping",Arguments=[target],Evaluate=(i,e)=>Trade(i,e)?.SaleInProgress==true});
  c.RegisterAction(new(){Id=prefix+"readMarketValue",Category="Mining",MenuGroup="Market",DisplayName="Read market payout, progress or result",Arguments=[target,new("refined","Refined ore",VariableValue.FromBoolean(true)),new("field","Value",VariableValue.FromString("Live net price")){Choices=["Live net price","Buy price","Maximum buy quantity","Guaranteed price","Shipping progress","Locked payout","Last payout","Last gain or shortfall","Delivery capacity","Exchange fee percent","Demand change seconds"]},new("variable","Output variable",VariableValue.FromString("MarketValue"))],Execute=(i,e)=>{
   if(Trade(i,e) is not {} t)return;bool refined=EventValueResolver.GetBoolean(i,"refined",e,true);double value=EventValueResolver.GetString(i,"field",e) switch{"Live net price"=>t.LiveQuote(refined),"Buy price"=>t.BuyQuote(refined),"Maximum buy quantity"=>t.MaximumBuyQuantity(refined),"Guaranteed price"=>t.GuaranteedQuote(refined),"Shipping progress"=>t.SaleProgress,"Locked payout"=>t.LockedSaleCredits,"Last payout"=>t.LastSaleTotal,"Last gain or shortfall"=>t.LastSaleAdvantage,"Delivery capacity"=>t.DeliveryCapacity,"Exchange fee percent"=>t.ExchangeFeePercent,"Demand change seconds"=>t.DemandSecondsRemaining,_=>0};string name=EventValueResolver.GetString(i,"variable",e,"MarketValue");if(!string.IsNullOrWhiteSpace(name))e.Self.Variables.Set(name,VariableValue.FromNumber(value));
  }});
  c.RegisterAction(new(){Id=prefix+"chooseMarketMethod",Category="Mining",MenuGroup="Mining Interface",DisplayName="Choose live market or delivery contracts",Arguments=[new("target","Mining interface",VariableValue.FromString("Self")){IsObjectReference=true},new("guaranteed","Delivery contracts",VariableValue.FromBoolean(false))],Execute=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningBusinessUi3D>()?.SelectMarketMethod(EventValueResolver.GetBoolean(i,"guaranteed",e))});
 }
}
